import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"40、【解】 坎下震上","description":"溫公易說 - 40、【解】 坎下震上","frontmatter":{"title":"40、【解】 坎下震上","description":"溫公易說 - 40、【解】 坎下震上"},"headers":[],"relativePath":"classics/wengong/041.md","filePath":"classics/wengong/041.md"}'),l={name:"classics/wengong/041.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_40、【解】-坎下震上" tabindex="-1">40、【解】 坎下震上 <a class="header-anchor" href="#_40、【解】-坎下震上" aria-label="Permalink to “40、【解】 坎下震上”">​</a></h1><h3 id="彖曰-解-險以動-動而免乎險-解。解-利西南-往得眾也。其來複吉-乃得中也。有攸往-夙吉-往有功也。天地解而雷雨作-雷雨作而百果草木皆甲坼。解之時-大矣哉。" tabindex="-1">彖曰：解，險以動，動而免乎險，解。解，利西南，往得眾也。其來複吉，乃得中也。有攸往，夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之時，大矣哉。 <a class="header-anchor" href="#彖曰-解-險以動-動而免乎險-解。解-利西南-往得眾也。其來複吉-乃得中也。有攸往-夙吉-往有功也。天地解而雷雨作-雷雨作而百果草木皆甲坼。解之時-大矣哉。" aria-label="Permalink to “彖曰：解，險以動，動而免乎險，解。解，利西南，往得眾也。其來複吉，乃得中也。有攸往，夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之時，大矣哉。”">​</a></h3><p>解無所往，其來複吉，有攸往，夙吉何也？夫能濟難者，存乎中。能有功者，存乎時。時未可往而用之太速，則不達。時可以往而應之太緩，則無功。故上六藏器於身，待時而動，君子韙之。</p><h3 id="象曰-雷雨作-解。君子以赦過宥罪。" tabindex="-1">象曰：雷雨作，解。君子以赦過宥罪。 <a class="header-anchor" href="#象曰-雷雨作-解。君子以赦過宥罪。" aria-label="Permalink to “象曰：雷雨作，解。君子以赦過宥罪。”">​</a></h3><h3 id="初六-無咎-象曰-剛柔之際-義無咎也。" tabindex="-1">初六：無咎 象曰：剛柔之際，義無咎也。 <a class="header-anchor" href="#初六-無咎-象曰-剛柔之際-義無咎也。" aria-label="Permalink to “初六：無咎 象曰：剛柔之際，義無咎也。”">​</a></h3><h3 id="九二-田獲三狐-得黃矢-貞吉-象曰-九二貞吉-得中道也。" tabindex="-1">九二：田獲三狐，得黃矢，貞吉 象曰：九二貞吉，得中道也。 <a class="header-anchor" href="#九二-田獲三狐-得黃矢-貞吉-象曰-九二貞吉-得中道也。" aria-label="Permalink to “九二：田獲三狐，得黃矢，貞吉 象曰：九二貞吉，得中道也。”">​</a></h3><h3 id="六三-負且乘-致寇至-貞吝-象曰-負且乘-亦可醜也。自我致戎-又誰咎也。" tabindex="-1">六三：負且乘，致寇至，貞吝 象曰：負且乘，亦可醜也。自我致戎，又誰咎也。 <a class="header-anchor" href="#六三-負且乘-致寇至-貞吝-象曰-負且乘-亦可醜也。自我致戎-又誰咎也。" aria-label="Permalink to “六三：負且乘，致寇至，貞吝 象曰：負且乘，亦可醜也。自我致戎，又誰咎也。”">​</a></h3><h3 id="九四-解而拇-朋至斯孚-象曰-解而拇-未當位也。" tabindex="-1">九四：解而拇，朋至斯孚 象曰：解而拇，未當位也。 <a class="header-anchor" href="#九四-解而拇-朋至斯孚-象曰-解而拇-未當位也。" aria-label="Permalink to “九四：解而拇，朋至斯孚 象曰：解而拇，未當位也。”">​</a></h3><h3 id="六五-君子維有解-吉。有孚於小人-象曰-君子有解-小人退也。" tabindex="-1">六五：君子維有解，吉。有孚於小人 象曰：君子有解，小人退也。 <a class="header-anchor" href="#六五-君子維有解-吉。有孚於小人-象曰-君子有解-小人退也。" aria-label="Permalink to “六五：君子維有解，吉。有孚於小人 象曰：君子有解，小人退也。”">​</a></h3><h3 id="上六-公用射隼於高墉之上-獲之-無不利-象曰-公用射隼-以解悖也。" tabindex="-1">上六：公用射隼於高墉之上，獲之，無不利 象曰：公用射隼，以解悖也。 <a class="header-anchor" href="#上六-公用射隼於高墉之上-獲之-無不利-象曰-公用射隼-以解悖也。" aria-label="Permalink to “上六：公用射隼於高墉之上，獲之，無不利 象曰：公用射隼，以解悖也。”">​</a></h3>',10)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
